python3 - <<'PY'
import os, zipfile
import openpyxl
from openpyxl.utils import get_column_letter
import xml.etree.ElementTree as ET

SRC='/root/data/workbook.xlsx'
OUT='/root/output/result.xlsx'
TMP='/root/output/result_tmp.xlsx'

year_cols=list(range(8,13)) # H-L


def excel_percentile_inc(data, p):
    xs = sorted(float(x) for x in data)
    n = len(xs)
    if n == 0:
        return None
    if p <= 0:
        return xs[0]
    if p >= 1:
        return xs[-1]
    r = 1 + (n - 1) * p
    k = int(r)
    d = r - k
    if d == 0:
        return xs[k-1]
    return xs[k-1] + d * (xs[k] - xs[k-1])

# ---- write formulas (and fill Data year headers) ----
wb=openpyxl.load_workbook(SRC)
wsT=wb['Task']
wsD=wb['Data']

years=[wsT.cell(row=10,column=c).value for c in year_cols]
if any(y is None for y in years):
    raise RuntimeError('Missing Task year headers')

# Put year headers into Data row 20 H-L (were empty)
for y,c in zip(years, year_cols):
    wsD.cell(row=20,column=c).value = int(y)

# Blocks lookup formulas using Data year header row
blocks=[(12,17),(19,24),(26,31)]
for r0,r1 in blocks:
    for r in range(r0,r1+1):
        for c in year_cols:
            col_letter=get_column_letter(c)
            wsT.cell(row=r,column=c).value = (
                f"=INDEX(Data!$H$21:$L$38,"
                f"MATCH($D{r},Data!$D$21:$D$38,0),"
                f"MATCH({col_letter}$10,Data!$H$20:$L$20,0))"
            )

# Net flow
for i, tr in enumerate(range(35,41)):
    adm=12+i; dis=19+i; bed=26+i
    for c in year_cols:
        col_letter=get_column_letter(c)
        wsT.cell(row=tr,column=c).value = f"=({col_letter}{adm}-{col_letter}{dis})/{col_letter}{bed}*100"

# Stats
stat_rows={
    42: lambda col: f"=MIN({col}35:{col}40)",
    43: lambda col: f"=MAX({col}35:{col}40)",
    44: lambda col: f"=MEDIAN({col}35:{col}40)",
    45: lambda col: f"=AVERAGE({col}35:{col}40)",
    46: lambda col: f"=PERCENTILE({col}35:{col}40,0.25)",
    47: lambda col: f"=PERCENTILE({col}35:{col}40,0.75)",
}
for r in range(42,48):
    for c in year_cols:
        col_letter=get_column_letter(c)
        wsT.cell(row=r,column=c).value = stat_rows[r](col_letter)

# Weighted mean
for c in year_cols:
    col_letter=get_column_letter(c)
    wsT.cell(row=50,column=c).value = f"=SUMPRODUCT({col_letter}35:{col_letter}40,{col_letter}26:{col_letter}31)/SUM({col_letter}26:{col_letter}31)"

wb.save(OUT)

# ---- compute numeric values ----
# reload for clean reads
wb2=openpyxl.load_workbook(OUT, data_only=False)
wsT2=wb2['Task']
wsD2=wb2['Data']

# Lookup dict from Data
lookup={}
for r in range(21,39):
    code=wsD2.cell(row=r,column=4).value
    if not code:
        continue
    lookup[code]={}
    for y,c in zip(years, year_cols):
        lookup[code][int(y)] = wsD2.cell(row=r,column=c).value

values={}

def cref(r,c):
    return f"{get_column_letter(c)}{r}"

for r0,r1 in blocks:
    for r in range(r0,r1+1):
        code=wsT2.cell(row=r,column=4).value
        if code not in lookup:
            raise RuntimeError(f"Missing series code {code}")
        for y,c in zip(years, year_cols):
            values[cref(r,c)] = float(lookup[code][int(y)])

net_by_col={c:[] for c in year_cols}
for i,tr in enumerate(range(35,41)):
    adm=12+i; dis=19+i; bed=26+i
    for c in year_cols:
        nf = (values[cref(adm,c)] - values[cref(dis,c)]) / values[cref(bed,c)] * 100.0
        values[cref(tr,c)] = nf
        net_by_col[c].append(nf)

for c in year_cols:
    vals=net_by_col[c]
    xs=sorted(vals)
    values[cref(42,c)] = min(vals)
    values[cref(43,c)] = max(vals)
    values[cref(44,c)] = (xs[2]+xs[3])/2.0
    values[cref(45,c)] = sum(vals)/len(vals)
    values[cref(46,c)] = excel_percentile_inc(vals, 0.25)
    values[cref(47,c)] = excel_percentile_inc(vals, 0.75)

for c in year_cols:
    net=[values[cref(r,c)] for r in range(35,41)]
    bed=[values[cref(r,c)] for r in range(26,32)]
    values[cref(50,c)] = sum(n*w for n,w in zip(net,bed)) / sum(bed)

# ---- locate Task sheet xml ----
with zipfile.ZipFile(OUT,'r') as z:
    workbook_xml=z.read('xl/workbook.xml')
    rels_xml=z.read('xl/_rels/workbook.xml.rels')

ns_main='http://schemas.openxmlformats.org/spreadsheetml/2006/main'
ns_rel_off='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
ns_pkg='http://schemas.openxmlformats.org/package/2006/relationships'

wb_root=ET.fromstring(workbook_xml)
rels_root=ET.fromstring(rels_xml)

rid_to_target={}
for rel in rels_root.findall(f'{{{ns_pkg}}}Relationship'):
    rid_to_target[rel.attrib['Id']] = rel.attrib['Target']

sheet_path=None
for sheet in wb_root.find(f'{{{ns_main}}}sheets').findall(f'{{{ns_main}}}sheet'):
    if sheet.attrib.get('name')=='Task':
        rid=sheet.attrib.get(f'{{{ns_rel_off}}}id')
        target=rid_to_target[rid].lstrip('/')
        sheet_path = target if target.startswith('xl/') else 'xl/' + target
        break
